import { useMemo, useState } from 'react';
import { JxBadge, JxPagination, JxTable } from '@jinx-ui/react';

interface JxUser {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

interface UsersTableProps {
  users: JxUser[];
}

const PAGE_SIZE = 10;

function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);
  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visibleUsers = useMemo(
    () => users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [users, currentPage]
  );

  return (
    <div>
      <JxTable>
        <thead>
          <tr>
            <th>Имя</th>
            <th>Роль</th>
            <th>Статус</th>
          </tr>
        </thead>
        <tbody>
          {visibleUsers.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <JxBadge tone={user.active ? 'success' : 'default'}>
                  {user.active ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
        </tbody>
      </JxTable>
      <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
    </div>
  );
}

export default UsersTable;

